// Une seule ligne réservée par tour : une panne ne laisse qu'une ligne incertaine.
// File vide : aucun élément, le passage s'arrête ici.
return $input.all().filter((i) => i.json && i.json.id).slice(0, 1).map((i) => ({ json: i.json, pairedItem: { item: 0 } }));

const notif = $('Une notification à la fois').item.json;
const rdv = $('Récupérer le rdv').item.json;
const client = $('Récupérer le client').item.json;
const vehicule = $('Récupérer le véhicule').item.json;
const garage = $('Récupérer le garage').item.json;
const reserve = $('Une notification à la fois').item.json;
const nomAffiche = (garage && garage.nom_garage ? garage.nom_garage : 'Votre garage').replace(/["\\]/g, ' ').trim();
const nomVehicule = `${vehicule.marque || ''} ${vehicule.modele || ''}`.trim();
const immat = (vehicule && vehicule.immatriculation) ? ' (' + vehicule.immatriculation + ')' : '';
let texte = `Bonjour ${client.nom || ''},\n\nVotre véhicule ${nomVehicule}${immat} est prêt, vous pouvez venir le récupérer chez ${garage.nom_garage || 'notre garage'}.`;
if ($json.lien_paiement_final) {
  texte += `\n\nVous pouvez régler en ligne dès maintenant : ${$json.lien_paiement_final}`;
}
texte += `\n\nÀ bientôt,\n${nomAffiche}`;

const expediteur = `"${nomAffiche}" <nexorasolutions.france@gmail.com>`;
const repondreA = (garage && garage.email) ? garage.email : '';

return [{ json: { expediteur, repondreA, notif_id: reserve.id, id: notif.id, client_email: client.email || '', texte } }];

// Rien n'est encore parti. Lecture en panne (à reprendre), document introuvable ou
// adresse inutilisable (bloqué) : on le dit maintenant, au lieu de laisser le
// fournisseur échouer en « incertain ».
const LECTURES = ["Relire la notification","Récupérer le rdv","Récupérer le client","Récupérer le véhicule","Récupérer le garage"];
const lu = (n) => { try { return $(n).item.json || {}; } catch (e) { return { error: 'lecture non faite : ' + n }; } };
const texteErreur = (e) => (typeof e === 'string' ? e : (e && (e.message || e.description)) || 'erreur inconnue');
const pannes = LECTURES.map((n) => [n, lu(n)]).filter(([, j]) => j.error);
if ($json.error) pannes.push(['Construire le message', $json]);
if (pannes.length) {
  const [n, j] = pannes[0];
  return [{ json: { pret: false, panne: true, noeud_panne: n, motif_verification: 'lecture ou préparation impossible (' + n + '), rien n\'est parti : ' + String(texteErreur(j.error)).slice(0, 200) } }];
}
const doc = lu("Récupérer le rdv");
const m = $json;
const adresse = String(m.client_email || '');
let motif = null;
if (!doc.id) motif = 'document introuvable à la lecture, rien n\'est parti';
else if (!/^[^\s@<>"]+@[^\s@<>"]+\.[^\s@<>"]+$/.test(adresse)) motif = 'adresse du client absente ou invalide, rien n\'est parti';
else if (!String(m.texte || '').trim()) motif = 'message vide, rien n\'est parti';
return [{ json: { ...m, pret: motif === null, panne: false, motif_verification: motif } }];

// Classement d'un échec d'envoi SMTP (nœud « Envoyer la relance (email) »).
//
// Source unique : `construire.mjs` recopie cette fonction dans le nœud Code
// « Classer l'échec » ; `classerEchec.test.js` la vérifie.
//
// RÈGLE : on ne déduit la nature d'un échec QUE de ce qu'on sait situer dans
// l'échange SMTP. Un nombre à trois chiffres trouvé n'importe où dans un
// message (« 550 € », un numéro de rue, un identifiant) ne veut rien dire.
//
//   - Aucune connexion établie (refus, nom introuvable)      → a_reprendre
//   - Authentification refusée                                → a_reprendre
//   - Réponse du serveur à MAIL FROM, RCPT TO ou à la
//     commande DATA, AVANT la transmission du message :
//       4xx → a_reprendre            5xx → bloque
//   - Réponse du serveur APRÈS la transmission du message
//     (« Message failed ») : le serveur dit explicitement
//     qu'il n'a pas pris le message :
//       4xx → a_reprendre            5xx → bloque
//   - Tout le reste — connexion coupée, délai dépassé, erreur
//     inconnue — peut survenir après que le fournisseur a
//     accepté le message                                      → incertain
//
// `incertain` n'est jamais clos ni repris : la relance reste `envoi_en_cours`
// et l'écran dit « envoi à vérifier ».

function classerEchec(erreur) {
  const e = erreur && typeof erreur === "object" ? erreur : { message: erreur };
  const message = String(e.message || e.description || "").trim();
  const code = String(e.code || "").toUpperCase();
  const commande = String(e.command || "").toUpperCase();
  const reponse = Number.isInteger(e.responseCode) ? e.responseCode : null;
  const extrait = message.slice(0, 200);
  const issue = (resultat, motif) => ({ resultat, motif: `${motif}${extrait ? " : " + extrait : ""}` });

  // 1. Pas de connexion : rien n'a pu partir.
  if (["ECONNREFUSED", "ENOTFOUND", "EAI_AGAIN", "EDNS"].includes(code)
      || /^(?:connect ECONNREFUSED|getaddrinfo (?:ENOTFOUND|EAI_AGAIN))\b/.test(message)) {
    return issue("a_reprendre", "connexion au fournisseur impossible, rien n'est parti");
  }
  // 2. Authentification refusée : rien n'a pu partir.
  if (code === "EAUTH" || /^(?:Invalid login|Authentication (?:failed|not supported))\b/i.test(message)) {
    return issue("a_reprendre", "authentification refusée par le fournisseur, rien n'est parti");
  }

  // 3. Réponse SMTP située dans l'échange : champs structurés d'abord…
  let etape = null;
  let classe = null;
  if (reponse !== null && reponse >= 400 && reponse < 600) {
    classe = Math.floor(reponse / 100);
    if (["MAIL FROM", "RCPT TO", "DATA"].includes(commande)) etape = "avant";
    else if (commande === "DATA END" || commande === ".") etape = "apres";
  }
  // … sinon les formulations exactes de nodemailer, ancrées en début de message.
  if (etape === null) {
    const avant = message.match(/^(?:Can't send mail - all recipients were rejected|Mail command failed|Recipient command failed|Data command failed):\s*([45])\d\d\b/);
    const apres = message.match(/^Message failed:\s*([45])\d\d\b/);
    if (avant) { etape = "avant"; classe = Number(avant[1]); }
    else if (apres) { etape = "apres"; classe = Number(apres[1]); }
  }
  if (etape === "avant") {
    return classe === 5
      ? issue("bloque", "refus définitif du fournisseur avant le message")
      : issue("a_reprendre", "refus temporaire du fournisseur avant le message");
  }
  if (etape === "apres") {
    return classe === 5
      ? issue("bloque", "refus définitif du fournisseur après le message")
      : issue("a_reprendre", "refus temporaire du fournisseur après le message, non accepté");
  }

  // 4. Tout le reste : le message a pu être accepté. On ne rejoue pas.
  return issue("incertain", "issue inconnue, le message a pu être accepté");
}


const brut = $json.error && typeof $json.error === 'object' ? $json.error : { message: $json.error || $json.message || '' };
const c = classerEchec({ message: brut.message || $json.message || '', description: brut.description, code: brut.code || $json.code, responseCode: brut.responseCode ?? $json.responseCode, command: brut.command || $json.command });
const categorie = { a_reprendre: 'refus_temporaire', bloque: 'refus_definitif', incertain: 'envoi_incertain' }[c.resultat];
return [{ json: { resultat: c.resultat, motif: c.motif, categorie, noeud: "Notifier véhicule prêt (email)" } }];

// Vérification refusée : panne de lecture ou de préparation (à reprendre, plafonné)
// ou données manquantes (bloqué, un humain corrige).
if ($json.panne === true) {
  return [{ json: { resultat: 'a_reprendre', motif: $json.motif_verification, categorie: 'echec_avant_envoi', noeud: $json.noeud_panne } }];
}
return [{ json: { resultat: 'bloque', motif: $json.motif_verification, categorie: 'donnees_invalides', noeud: 'Vérifier avant envoi' } }];

// Expurgation d'un texte d'erreur avant de le journaliser.
//
// Source unique : `construire.mjs` recopie cette fonction dans les nœuds Code
// du socle et du journaliseur ; `expurger.test.js` la vérifie.
//
// Le journal des incidents est lu par des humains et survit aux lignes de
// file : il ne doit contenir ni adresse e-mail, ni lien (un lien public porte
// un jeton), ni clé, ni en-tête d'autorisation. On garde ce qui aide à
// comprendre : le code SMTP, le code réseau, le nom de l'étape.

function expurger(texte, longueur) {
  const max = Number.isInteger(longueur) ? longueur : 300;
  let t = texte === null || texte === undefined ? "" : String(texte);
  t = t
    .replace(/\b(?:https?|wss?):\/\/\S+/gi, "<lien>")
    .replace(/\b(?:Bearer|Basic)\s+[A-Za-z0-9._~+\/=-]+/gi, "<autorisation>")
    .replace(/\b(apikey|api_key|authorization|password|pass|token|jeton|secret)(["']?\s*[:=]\s*["']?)[^\s"',;}]+/gi, "$1$2<masqué>")
    .replace(/\beyJ[A-Za-z0-9_-]{8,}(?:\.[A-Za-z0-9_-]+){1,2}/g, "<jeton>")
    .replace(/\b(?:xkeysib|xsmtpsib|sk_live|sk_test|sb_secret)[-_][A-Za-z0-9_-]+/gi, "<clé>")
    .replace(/[A-Za-z0-9._%+-]+@[A-Za-z0-9.-]+\.[A-Za-z]{2,}/g, "<e-mail>")
    .replace(/\b[0-9a-f]{32,}\b/gi, "<empreinte>")
    .replace(/\s+/g, " ")
    .trim();
  return t.length > max ? t.slice(0, max - 1) + "…" : t;
}


const MAX_TENTATIVES = 3;
const notif = $('Une notification à la fois').item.json;
let tentatives = null;
try { tentatives = Number($('Relire la notification').item.json.tentatives); } catch (e) { tentatives = null; }
let { resultat, motif, categorie, noeud } = $json;
if (resultat === 'a_reprendre' && Number.isFinite(tentatives) && tentatives >= MAX_TENTATIVES) {
  resultat = 'bloque';
  categorie = categorie === 'refus_temporaire' ? 'refus_temporaire_repete' : categorie;
  motif = `échec temporaire répété (${tentatives} tentatives), mis de côté : ${motif}`;
}
const intervention = ['bloque', 'incertain'].includes(resultat);
return [{ json: {
  id: notif.id, file: "atelier", resultat, categorie, noeud, tentatives,
  motif: motif === null ? null : expurger(motif, 300),
  intervention,
} }];
